let exampleCode = `let furnace = device("d0")
let sensor = device("d1")

while true {
  let temp = l(sensor, "Temperature")

  if temp < 500 {
    s(furnace, "On", 1)
  } else {
    s(furnace, "On", 0)
  }

  %raw("yield")
}
`;

